      "activity_name": "U8 - JMX source implementation",
      "activity_description": "Implement JMX source module using Spring Integration JMX notification-listening adapter: MBean subscription configuration, notification-to-message conversion, and publication to the message broker.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-16",
      "activity_name": "U8 - JMX source tests",
